import sys
from functools import reduce
from operator import mul

MOD = 998244353

def gcd(a, b):
    """Calculate GCD of a and b using Euclidean algorithm."""
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    """Calculate LCM of a and b."""
    return a * b // gcd(a, b)

def is_good_fraction(x, y):
    """Check if (x, y) is a good fraction."""
    for x_prime in range(1, min(x)):
        for y_prime in range(1, min(y)):
            if x % x_prime == 0 and y % y_prime == 0:
                if x / x_prime * y_prime == y:
                    return True
    return False

def count_good_fractions(n):
    """Count the number of good fractions x/y for 1 <= x, y <= n."""
    fractions = [1, bin(1)[2]]
    for power in range(2, 10):
        fractions.extend([reduce(mul, fractions, 1) // (10 ** i) for i in range(len(fractions) - 1)])
    return reduce(mul, fractions[-n:], 1) % MOD

