from heapq import heapify, heappop, heappush

def max_edge_length_cost(m, paths):
    n = len(m)
    edges = [[] for _ in range(n)]
    for ai, bi, length in paths:
        edges[ai - 1].append((bi - 1, length))
        edges[bi - 1].append((ai - 1, length))

    def max_paving_path_length(marking):
        path_indices = [edges[u][v][0] if marking[u][v] else -1 for u in range(n) for v in range(n)]
        heapq.heapify(path_indices)
        while path_indices:
            if not path_indices:
                return -1
            curr_ind = heapq.heappop(path_indices)
            if marking[curr_ind[0]][curr_ind[1]]:
                return -1
            marking[curr_ind[0]][curr_ind[1]] = True
            curr_length = edges[curr_ind[0]][curr_ind[1]][1]
            yield curr_length
            for next_ind in ((curr_ind[1], curr_ind[0]),):  # Add both directions, as path directions do not matter here
                heapq.heappush(path_indices, (next_ind, edges[next_ind][curr_ind][1]))

    return max(max_paving_path_length(marking).__next__())


