MOD = 998244353

def mod_pow(x, n):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * x) % MOD
        x = (x * x) % MOD
        n = n // 2
    return result

def get_good_count(n):
    count = 0
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            gcd = mod_pow(min(x, y), MOD - 2)
            num = x // gcd
            den = y // gcd
            if den * num == y * x and num % 10 == x % 10 and den != 1:
                count += 1
    return count % MOD

