from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

def simplify_fraction(numerator, denominator):
    common_divisor = gcd(numerator, denominator)
    return numerator // common_divisor, denominator // common_divisor

def calculate_probability(input_n, card_numbers):
    total_games = pow(2, input_n)
    petya_wins = 0
    for permutation in range(1, pow(2, input_n) // 2 + 1):
        game_counts = bin(permutation).count('1')
        card_values = [card_numbers[i] if (i + game_counts) % 2 else 1 - card_numbers[i] for i in range(input_n)]
        if sum(card_values) % 2 == 1:
            petya_wins += 1
    return simplify_fraction(petya_wins, total_games)

