import sys
from collections import defaultdict
from heapq import heapify, heappush, heappop
from typing import Tuple

class AligningDijkstra:
    def __init__(self, adj_lst):
        """Initializes the AligningDijkstra object and sets up all buckets."""
        self.adj_lst = adj_lst
        self._dist = dict()
        for src in range(1, self.adj_lst[0].len + 1):
            self._dist[src] = float('inf')
        self._dist[self.adj_lst[0][0]] = 0
        self._visited = set()
        self._heap = []
        heappush(self._heap, (self._dist[self.adj_lst[0][0]], 0, self.adj_lst[0][0]))
        while self._heap:
            current_dist, curr_src, curr_target = heappop(self._heap)
            if curr_target not in self._visited: 
                if curr_target not in self._dist:
                    self._dist[curr_target] = current_dist
                    for weight, next_target in self.adj_lst[curr_target].items():
                        diff = current_dist + weight 
                        if diff < self._dist[next_target]:
                            self._dist[next_target] = diff
                            heappush(self._heap, (diff, next_target, curr_target))
                self._visited.add(curr_target)

    def path_length(self, final_path):
        """Given a final path, climbs up to find the path with maximum weight within that path."""
        if final_path[0] == 0:
            _final_path = final_path
            final_path = self._dist[final_path[2]]
            final_path += self._dist[final_path[1]]
            if final_path[1] == 0:
                final_path = self._dist[final_path[2]]
                final_path += self._dist[self._dist[final_path[1]]]
                _final_path = self._dist[final_path[2]]
        return max(_final_path, final_path)


def bk(sz: int, paths: list[tuple[int, int, int]]) -> int or -1:
    """Determine the minimum path length after the next given path is connected."""
    adj_lst = defaultdict(lambda: defaultdict(int))
    for a, b, weight in paths:
        adj_lst[a][b] += weight 
        adj_lst[b][a] += weight
    align = AligningDijkstra(adj_lst)
    for i, weight in enumerate(paths):
        src, dst, weight = weight
        dist_to = align.path_length([i, src, dst])
        if dist_to == float('inf'):
            return -1
    return min(align._dist.values())


