import sys

def build_schedule(n, m, paths):
    schedule = []
    odd_count = 0
    even_count = 0
    for i, path in enumerate(paths):
        count = path.count('Yes')
        odds = count // 2
        evens = (count + 1) // 2
        if count % 2:
            odd_count += odds
            even_count += evens
        for _ in range(odds + evens):
            if schedule[-1].isdigit():
                schedule[-1] += path
            else:
                schedule[-1] = 'Yes' * odds + schedule[-1] + 'Yes' * (evens - odds)
        schedule.append('Yes' * odds + path[3:] + 'Yes' * (evens - odds))
    return [even_count, odd_count]

def main():
    n, m = map(int, input().split())
    paths = [input().split() for _ in range(m)]
    even_count, odd_count = build_schedule(n, m, paths)
    if odd_count != n:
        print(-1)
    else:
        expected_length = sys.maxsize
        for edge in paths:
            even_count -= 2
            odd_count -= 1
            current_length = edge[3:]
            if odd_count + even_count > n:
                break
            elif odd_count + even_count == n:
                expected_length = min(expected_length, int(current_length))
            odd_count += 1
            even_count += 1
        if expected_length != sys.maxsize:
            print(expected_length)
        else:
            print('-1')

if __name__ == "__main__":
    main()
