import collections

class Graph:
    def __init__(self, n):
        self.graph = collections.defaultdict(list)
        self.number = n

    def add_edge(self, u, v):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, v, parent, visited):
        visited[v] = True
        for neighbor in self.graph[v]:
            if not visited[neighbor]:
                count = 0
                # Find a cycle
                while neighbor != v and self.directed(neighbor, v, neighbor, parent):
                    visited[neighbor] = visited[neighbor] or count != 0
                    parent[neighbor] = v
                    neighbor = self.graph[neighbor][0]
                    count += 1
        return visited

    def direct_path_any_cycle(self, x, y, l, candidate, visited):
        l += 1
        visited[x] = True
        candidate.append(x)
        if len(candidate) == self.number:
            return True, visited, candidate, l
        else:
            if x > y:
                return self.direct_path_any_cycle(y, x + 1, l, candidate, visited)
            elif y > x:
                candidate.append(y)
                y += 1
                return self.direct_path_any_cycle(x + 1, y, l, candidate, visited)

    def check_connected_cycle(self, cand):
        choice = []
        for cand_index in cand:
            for cp in range(self.number):
                l = 1
                start_vertex = cp
                check_path = self.direct_path_any_cycle(start_vertex, cand_index, l, choice, visited=[False]*self.number)
                if check_path[0]:
                    choice.append(cp)
                else:
                    choice.append(False)
        return len(choice), choice

    def cycle_check(self, cand):
        cycle_start_vertex = cand[0]
        cycle_end_vertex = cand[1]
        return self.directed(cycle_start_vertex, cycle_end_vertex, cycle_start_vertex, cycle_end_vertex)

    def directed(self, start_vertex, cycle_end_vertex, cycle_start, cycle_end):
        if cycle_end_vertex == start_vertex:
            cycle_end = start_vertex
            return self.directed(cycle_start, cycle_end, cycle_start, cycle_end)

        candidate = [cycle_end_vertex]
        has_cycle, candidate_next, dfa, l = self.direct_path_any_cycle(start_vertex, cycle_end, l - 1, candidate)
        if not has_cycle:
            return False
        elif has_cycle:
            for idx in range(len(dfa)):
                cycle_end = dfa[idx]
                has_cycle_new, candidate_next, dfa, l = self.direct_path_any_cycle(cycle_start, cycle_end, l - 1, candidate_next)
                if not has_cycle_new:
                    return False
                elif has_cycle_new:
                    for idx in range(len(dfa)):
                        cycle_end = dfa[idx]
                        has_cycle = self.cycle_check(cycle_end)
                        if not has_cycle:
                            return False
        return True


