import sys

def sort_deck(n, cards):
    # Assuming n is odd and cards are 2n long
    if n % 2 == 0:
        return -1  # Cannot be sorted

    card_map = {value: [] for value in range(1, 2 * n + 1)}
    inverse_map = {value: [] for value in range(1, 2 * n + 1)}

    # Create lists of front, back, inverse fronts and inverse backs
    for i, (a, b) in enumerate(cards):
        card_map[a].append(i)
        inverse_map[b].append(i)

    total_flips = 0

    # Process cards 1 through (n/2)
    for i in range(n // 2):
        # Check if swap is needed
        if card_map[i + 1] == card_map[i] and inverse_map[2 * i + 1] == inverse_map[2 * i + 2]:
            total_flips += 1
        else:
            card_map[card_map[i + 1]].append(card_map[i])
            card_map[card_map[i]].remove(card_map[i])
            inverse_map[inverse_map[2 * i + 1]].append(inverse_map[2 * i + 2])
            inverse_map[inverse_map[2 * i + 2]].remove(inverse_map[2 * i + 2])
            total_flips += 2

            for j in range(2):
                while card_map[i + 1 + j]:
                    if set([card_map[i + 1 + j][-1] // 2, card_map[i + 1 + j][-2] // 2]) != {1, 2}:
                        card_map[card_map[i + 1 + j][-1]].append(card_map[i + 1 + j].removecard(j))
                    total_flips += 2 + abs(card_map[i + 1 + j][-1] - card_map[i + 1 + j][-2])
    return total_flips
