    # Calculate the greatest common divisor of all ai values
    gcd_val = 0
    primes = gen_prime_range(10)
    for card in cards:
        val = card[0]
        if isinstance(val, int):
            gcd_val = lcm(gcd_val, val)
        else:
            val //= gcd_val
            for prime in primes:
                if val % prime == 0:
                    val //= prime
            gcd_val *= val

    # Convert the gcd value to a reduced fraction
    norm_gcd = gcd_val
    for divisor in divisors(norm_gcd):
        norm_gcd /= divisor
        numerator = Rationals(norm_gcd)
        i = 0
        while 0 < num + denominator(i) and num * (denominator(i) + 1) <= denominator(denominator(i) + 1) * num:
            i += 1
        inv = mod_inverse(denominator(i) + 1, denominator(denominator(i) + 1))
        numerator = num * inv
        if num + denominator(i) == 0:
            norm_gcd = Rational(0, 1)

    lcm_val = norm_gcd * gcd_val
    total_piles = gcd_val + lcm_val

    petya_wins = 2**total_piles - 2**(n - 1)

    return petya_wins / (2**total_piles)

