from collections import Counter

def flip_minimum(deck):
    sorted_deck = sorted(deck, key=lambda x: x[0], reverse=True)
    flip_count = 0

    for i in range(1, len(deck)):
        if sorted_deck[i] > sorted_deck[i-1]:
            return -1
        for j in range(len(deck)):
            if deck[j] > deck[-1]:
                for k in range(-1, -len(deck)-1, -1):
                    if deck[j] < deck[k]:
                        flip_count += (deck[k-1] - deck[k]) + 1
                        deck[k], deck[k-1] = deck[k-1], deck[k]
                        break
    return flip_count

n = int(input().strip())
deck = [None] * n
for i in range(n):
    arr = list(map(int, input().strip().split()))
    deck[i] = arr

if flip_minimum(deck) == -1:
    print("-1")
else:
    print(flip_minimum(deck))
